package feature_test

import (
	"context"
	"strings"
	"testing"

	"github.com/Subject-Void-LLC/the-pleiades/internal/catalog/win/feature"
	"github.com/Subject-Void-LLC/the-pleiades/pkg/collection"
)

// TestInstall_Registered is a starter test, generated by
// pleiades forge new-collection: it proves "win.feature.install" registered itself
// through this package's own init(), with the manifest fields given at
// generation time.
func TestInstall_Registered(t *testing.T) {
	d, ok := collection.Lookup("win.feature.install")
	if !ok {
		t.Fatalf("collection.Lookup(%q) found nothing; did this package's init() run?", "win.feature.install")
	}
	if d.Manifest.Status != collection.StatusDeclared {
		t.Errorf("Manifest.Status = %v, want %v", d.Manifest.Status, collection.StatusDeclared)
	}
	if d.Manifest.ExecutionContext.RequiresElevation != true {
		t.Errorf("Manifest.ExecutionContext.RequiresElevation = %v, want %v",
			d.Manifest.ExecutionContext.RequiresElevation, true)
	}
}

// TestInstall_NotImplemented is a starter, table-driven proof of
// the "declared is not implemented" guardrail: the stub must return an
// explicit error, never success. Replace this table as real parameter
// cases are added once Install is actually implemented.
func TestInstall_NotImplemented(t *testing.T) {
	tests := []struct {
		name   string
		params map[string]any
	}{
		{name: "no params", params: nil},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := feature.Install(context.Background(), nil, nil, tt.params)
			if err == nil {
				t.Fatal("expected an explicit not-implemented error, got nil")
			}
			if !strings.Contains(err.Error(), "not implemented") {
				t.Errorf("error = %q, want it to mention \"not implemented\"", err.Error())
			}
		})
	}
}
